from pathlib import Path
from datetime import datetime
from zoneinfo import ZoneInfo
import sys,json,time,threading,subprocess,gzip,hashlib,shutil,importlib.util

R=Path(__file__).resolve().parent;W=R.parent;BASE=W/'r3_restore/r2/buffer_growth'
def put(path,value):
    p=path.with_suffix(path.suffix+'.tmp');p.write_text(json.dumps(value,indent=2)+'\n');p.replace(path)
def status(stage,**kw):put(R/'STATUS.json',{'stage':stage,'updated_jakarta':datetime.now(ZoneInfo('Asia/Jakarta')).isoformat(),**kw})
def load(p):return json.loads(p.read_text())
spec=importlib.util.spec_from_file_location('r3_runner_for_r4',W/'r3_research/run_r3.py');runner=importlib.util.module_from_spec(spec);spec.loader.exec_module(runner)
runner.ROOT=R;runner.BIN=R/'work_r4/replay/Replay.dll'
runner.EXPECTED=load(R/'BUILD.json')['binary_sha256']
assert hashlib.sha256(runner.BIN.read_bytes()).hexdigest()==runner.EXPECTED

def setup():
    seed=load(BASE/'BUFFER_EUR_BTC_V2_CANDIDATE.json')[0]
    control=dict(seed,PortfolioCapPct=20.75);put(R/(control['Id']+'.json'),[control])
    profiles=[]
    for cap in [17.5,15,12.5,10]:
        p=dict(seed,Id='R4_CAP_'+str(cap).replace('.','p'),PortfolioCapPct=cap);profiles.append(p);put(R/(p['Id']+'.json'),[p])
    put(R/'PROFILES.json',profiles)
    for name in ['fresh_xau_tape.json','fresh_eur_tape.json']:
        p=R/name
        if not p.exists():p.symlink_to(W/'buffer_growth'/name)
    for name in ['FROZEN_BUFFER_LOCK.json','aggregate_growth.py']:shutil.copy2(BASE/name,R/name)
    audit=(BASE/'audit_growth.py').read_text();needle=" checks['btc_terminal_safety']="
    assert audit.count(needle)==1
    audit=audit.replace(needle," checks['portfolio_cap_matches_config']=cfg['Risk']==profile.get('PortfolioCapPct',20.75) and 0<cfg['Risk']<=20.75\n"+needle)
    (R/'audit_growth.py').write_text(audit)
    put(R/'PLAN.json',{'created_jakarta':datetime.now(ZoneInfo('Asia/Jakarta')).isoformat(),'user_goal':'Highest ending balance while measured max equity DD is strictly below 60% across all six A/B x costs1/1.5/2; no claim this combination is guaranteed.','frozen_R2_reference':load(W/'r3_research/FROZEN_R2_REFERENCE.json'),'source_seed':seed,'profiles':profiles,'isolated_change':'Replay-only portfolio sizing risk cap. XAU code/parameters, EUR and BTC parameters, entry/exit logic, delay, costs, input data and 2019-2026 cutoff unchanged. Native fixed 20.75 guard unchanged.','steps':['Default20.75 B cost2 replay, compare all original R2 root fields; stop on parity failure.','Screen four caps on B costs2 and1.','Full six for every screened candidate with DD<60 on both B endpoints.','Choose highest minimum normal A/B ending balance among fully audited six-scenario candidates with worstDD<60; report Pareto/tradeoffs and all failed old BUFFER thresholds.'],'old_BUFFER_thresholds_retained_for_comparison':{'normal_A_floor':988747417.2738367,'normal_B_floor':938466200.2239354,'cost2_floor':842853657.6189626,'old_dd_ceiling':72.21320348415222},'DD_target_is_not_early_termination':True,'no_topups':True,'synthetic_M1':True,'independent_OOS':False,'live_changes':False,'R3_ongoing_work_preserved':True,'storage':'Library capacity is currently full. Source/checkpoint can be preserved on the authorized research branch; do not claim final raw archive saved without successful receipt.'})
    return control,profiles

def audit():
    with (R/'audit.log').open('w') as f:subprocess.run([sys.executable,str(R/'audit_growth.py')],stdout=f,stderr=f,check=True)
    rows=load(R/'RESULTS.json');assert rows and all(x['pass'] for x in rows),'Full audit failed'
    return rows

def parity(control):
    runner.replay([control],'CONTROL_B_C2',2,'B')
    with gzip.open(R/'CONTROL_B_C2'/f"{control['Id']}_B_cost2.json.gz",'rt') as f:new=json.load(f)
    with gzip.open(BASE/'COMBINED_B_C2'/f"{control['Id']}_B_cost2.json.gz",'rt') as f:old=json.load(f)
    checks={k:k in new and new[k]==v for k,v in old.items()}
    result={'pass':all(checks.values()),'fields':checks,'old_root_fields':len(old),'R2_binary_sha256':'79b61fb0565957ed792a67c8c0de08e18c5a5e8b2b892ccb1c320f9ad9b5e653','R4_binary_sha256':runner.EXPECTED,'scope':'Default 20.75 cap on full B cost2, all original root fields exact. No changed name or excluded fields.'}
    put(R/'DEFAULT_PARITY.json',result);assert result['pass'],'Default behavior differs from frozen R2; stop research scores'
    print('DEFAULT_FULL_PARITY_PASS',flush=True)

def pair(profiles,first,second):
    loaded=threading.Event();errors=[]
    def work():
        try:runner.replay(profiles,*first,on_loaded=loaded)
        except BaseException as e:errors.append(repr(e));loaded.set()
    t=threading.Thread(target=work);t.start()
    while not loaded.wait(15):print('WAIT first input loading',flush=True)
    if errors:raise RuntimeError(errors)
    runner.replay(profiles,*second);t.join()
    if errors:raise RuntimeError(errors)

def finish(rows):
    configs={x['Id']:x for x in load(R/'PROFILES.json')};full=[];screens=[]
    for pid in configs:
        group=[x for x in rows if x['id']==pid]
        screens.append({'id':pid,'cap':configs[pid]['PortfolioCapPct'],'completed_scenarios':len(group),'rows':[{k:x[k] for k in ['way','cost','balance','dd','pass']} for x in group]})
        if len(group)!=6:continue
        assert {(x['way'],x['cost']) for x in group}=={(w,c) for w in 'AB' for c in [1,1.5,2]}
        n={x['way']:x for x in group if x['cost']==1};worst=max(x['dd'] for x in group);stress=min(x['balance'] for x in group if x['cost']==2)
        original={'normal_A_improves':n['A']['balance']>988747417.2738367,'normal_B_improves':n['B']['balance']>938466200.2239354,'cost2_floor':stress>=842853657.6189626,'old_DD_ceiling':worst<=72.21320348415222}
        prior=load(BASE/'COMBINED_ACCEPTANCE.json');frozen={(x['way'],x['cost'],x['symbol']):x['frozen_pnl'] for x in prior['pnl_comparison']}
        original['EUR_BTC_pnl_all6_improve']=all(x['symbols'][sym]['pnl']>frozen[x['way'],x['cost'],sym] for x in group for sym in ['EURUSD','BTCUSD'])
        full.append({'id':pid,'cap':configs[pid]['PortfolioCapPct'],'normal_A':n['A']['balance'],'normal_B':n['B']['balance'],'normal_min':min(x['balance'] for x in n.values()),'worst_dd':worst,'cost2_min_balance':stress,'target_pass':worst<60 and all(x['pass'] for x in group),'old_acceptance_checks':original,'old_acceptance_pass':all(original.values())})
    eligible=[x for x in full if x['target_pass']];best=max(eligible,key=lambda x:(x['normal_min'],x['cost2_min_balance'])) if eligible else None
    result={'full_six':full,'screening':screens,'best_balance_under_60_DD':best,'search_complete_for_declared_grid':True,'not_global_optimum_proof':True,'strict_below_60':True,'frozen_R2_unchanged':True,'LIVE_unchanged':True,'native_tick':False,'independent_OOS':False}
    put(R/'ACCEPTANCE.json',result)
    lines=['# R4: saldo terbesar dengan batas DD <60%','',f"Skenario selesai dan diaudit: {len(rows)} termasuk kontrol. Batas sizing global yang diuji:17,5%,15%,12,5%,10%. XAU tetap; R2/BUFFER V1/LIVE tidak diubah.",'','|ID|Cap %|Normal A USD|Normal B USD|Worst DD enam %|Minimum saldo2× USD|Target <60 lulus|','|---|---:|---:|---:|---:|---:|---|']
    for x in full:lines.append(f"|{x['id']}|{x['cap']}|{x['normal_A']:,.2f}|{x['normal_B']:,.2f}|{x['worst_dd']:.6f}|{x['cost2_min_balance']:,.2f}|{x['target_pass']}|")
    lines+=['',f"Kandidat saldo tertinggi yang memenuhi DD<60 pada seluruh enam: {best['id'] if best else 'BELUM ADA pada grid ini'}.",'','Pemilihan memaksimalkan saldo normal terendah lintas A/B, bukan meminimalkan DD tanpa memperhatikan saldo. Kegagalan batas profit lama tetap tercantum di ACCEPTANCE.json. Saldo1miliar tetap tujuan eksplorasi; tidak diasumsikan bertahan setelah cap diperkecil.','','Semua replay sampai cutoff sama; tidak dipotong ketika DD mendekati60. Compounding tetap, $100 tanpa top-up. Jalur OHLC sintetis M1, delay2detik, stress komisi/slippage/funding dengan spread tetap. Belum native tick, OOS atau bukti eksekusi broker nyata.']
    (R/'REPORT.md').write_text('\n'.join(lines)+'\n');print(json.dumps(result,indent=2),flush=True)
    status('complete',complete=True,best=best,raw_durable_save_confirmed=False)

def main():
    control,profiles=setup();status('default_parity_control_running',complete=False)
    parity(control);audit();status('screening_four_caps',complete=False)
    pair(profiles,('SCREEN_B_C2',2,'B'),('SCREEN_B_C1',1,'B'))
    rows=audit();selected=[]
    for p in profiles:
        group=[x for x in rows if x['id']==p['Id'] and x['way']=='B' and x['cost'] in [1,2]]
        assert len(group)==2
        if max(x['dd'] for x in group)<60:selected.append(p)
    put(R/'SELECTION.json',{'selected_for_full6':[p['Id'] for p in selected],'rule':'Both B1/B2 DD strictly below60 with audits; normal balance objective assessed after full6.','not_final':True})
    if selected:
        status('full_six_validation',complete=False,selected=[x['Id'] for x in selected])
        pair(selected,('FINAL_A_C2',2,'A'),('FINAL_A_C1',1,'A'))
        pair(selected,('FINAL_A_C1.5',1.5,'A'),('FINAL_B_C1.5',1.5,'B'))
        rows=audit()
    subprocess.run([sys.executable,str(R/'aggregate_growth.py')],check=True)
    finish(rows)

if __name__=='__main__':
    try:main()
    except BaseException as e:status('error',complete=False,error=repr(e));raise

